7	function showMaskedApiKey() {
8	  var input = document.getElementById('apiKey');
9	  var masked = document.getElementById('apiKeyMasked');
10	  var eye = document.getElementById('apiKeyEye');
11	  if (!input || !masked || !eye) return;
12	  if (input.value && input.value.startsWith('sk-')) {
13	    input.style.display = 'none';
14	    eye.style.display = 'none';
15	    masked.style.display = 'block';
16	    masked.textContent = maskApiKey(input.value);
17	  }
18	}
