20	function editApiKey() {
21	  var input = document.getElementById('apiKey');
22	  var masked = document.getElementById('apiKeyMasked');
23	  var eye = document.getElementById('apiKeyEye');
24	  if (!input || !masked || !eye) return;
25	  input.style.display = 'block';
26	  eye.style.display = 'block';
27	  masked.style.display = 'none';
28	  input.type = 'password';
29	  setTimeout(function() { input.focus(); }, 50);
30	}
