32	function onApiKeyFocus() { /* 입력 모드 유지 */ }
33	function onApiKeyBlur() {
34	  // 빈 값이거나 형식이 맞으면 마스킹 모드로
35	  var input = document.getElementById('apiKey');
36	  if (input && input.value && input.value.startsWith('sk-')) {
37	    setTimeout(showMaskedApiKey, 200); // 클릭 이벤트 우선 처리
38	  }
39	}
