41	function toggleApiKeyVisibility() {
42	  var input = document.getElementById('apiKey');
43	  var eye = document.getElementById('apiKeyEye');
44	  if (!input || !eye) return;
45	  if (input.type === 'password') {
46	    input.type = 'text';
47	    eye.textContent = '🙈';
48	  } else {
49	    input.type = 'password';
50	    eye.textContent = '👁️';
