54	// PII 마스킹 (로그용)
55	function maskPII(str) {
56	  if (!str) return str;
57	  return String(str)
58	    .replace(/(\d{3})-?(\d{3,4})-?(\d{4})/g, '$1-****-$3')  // 전화번호
59	    .replace(/(\d{4})-?(\d{2})-?(\d{2})/g, '$1-**-**');     // 생년월일
60	}
