62	// ─────── 운영 모니터링: 에러 로깅 + 토큰 사용량 ───────
63	var ERROR_LOG_MAX = 100;
64	var apiUsage = { calls: 0, inputTokens: 0, outputTokens: 0, byModel: {} };
65	
66	function loadApiUsage() {
67	  try {
68	    var saved = JSON.parse(localStorage.getItem('madi_api_usage') || '{}');
69	    if (saved.calls !== undefined) apiUsage = saved;
70	  } catch(e) {}
71	}
72	
73	function saveApiUsage() {
74	  try { localStorage.setItem('madi_api_usage', JSON.stringify(apiUsage)); } catch(e) {}
75	}
76	
77	function recordApiUsage(model, inputTokens, outputTokens) {
78	  apiUsage.calls = (apiUsage.calls || 0) + 1;
79	  apiUsage.inputTokens  = (apiUsage.inputTokens  || 0) + (inputTokens  || 0);
80	  apiUsage.outputTokens = (apiUsage.outputTokens || 0) + (outputTokens || 0);
81	  if (!apiUsage.byModel[model]) apiUsage.byModel[model] = { calls: 0, inputTokens: 0, outputTokens: 0 };
82	  apiUsage.byModel[model].calls++;
83	  apiUsage.byModel[model].inputTokens  += (inputTokens  || 0);
84	  apiUsage.byModel[model].outputTokens += (outputTokens || 0);
85	  saveApiUsage();
86	}
