88	function estimateCost() {
89	  // Anthropic 가격 (USD per 1M tokens) — 2026.05 기준, 변경 시 수정 필요
90	  // 최신 가격: https://www.anthropic.com/pricing
91	  var prices = {
92	    'claude-sonnet-4-6':           { input: 3.00,  output: 15.00 },
93	    'claude-haiku-4-5-20251001':   { input: 0.80,  output: 4.00  }
94	  };
95	  var totalUSD = 0;
96	  Object.keys(apiUsage.byModel || {}).forEach(function(m) {
97	    var p = prices[m] || prices['claude-sonnet-4-6'];
98	    var u = apiUsage.byModel[m];
99	    totalUSD += (u.inputTokens / 1000000) * p.input + (u.outputTokens / 1000000) * p.output;
100	  });
101	  return totalUSD;
102	}
