104	function resetApiUsage() {
105	  showConfirm('API 사용량 통계를 초기화할까요?', function() {
106	    apiUsage = { calls: 0, inputTokens: 0, outputTokens: 0, byModel: {} };
107	    saveApiUsage();
108	    renderDebugInfo();
109	    showToast('🔄 API 사용량 초기화됨');
110	  }, { danger: false });
111	}
