113	// 에러 로그에 토큰·비밀번호·API 키가 흘러들어가지 않도록 마스킹
114	function _sanitizeForErrorLog(s) {
115	  if (s === null || s === undefined) return '';
116	  return String(s)
117	    .replace(/sk-ant-[A-Za-z0-9_\-]{20,}/g, 'sk-ant-***')
118	    .replace(/eyJ[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}/g, 'JWT_***')
119	    .replace(/Bearer\s+[A-Za-z0-9_\-\.=+\/]{20,}/gi, 'Bearer ***')
120	    .replace(/(password|pwd|secret|token|api[_\-]?key)\s*[:=]\s*"?[^"\s,&]+/gi, '$1=***')
121	    .replace(/[?&](password|pwd|token|api[_\-]?key)=[^&\s]*/gi, '&$1=***');
122	}
