124	// 에러 로그 저장
125	function pushErrorLog(entry) {
126	  // 1) 기존 sessionStorage 저장 (즉시 조회 가능, 변경 없음)
127	  try {
128	    var arr = JSON.parse(sessionStorage.getItem('madi_error_log') || '[]');
129	    arr.push(entry);
130	    if (arr.length > ERROR_LOG_MAX) arr = arr.slice(-ERROR_LOG_MAX);
131	    sessionStorage.setItem('madi_error_log', JSON.stringify(arr));
132	  } catch(e) {}
133	
134	  // 2) Supabase에도 비동기 저장 (영구 보관 + 슈퍼어드민 조회용)
135	  if (window._errorLogSending) return;   // 무한 루프 방지
136	  if (!window.currentUser) return;        // 로그인 전 에러는 서버 저장 안 함
137	  window._errorLogSending = true;
138	  try {
139	    var payload = {
140	      user_id:    String((window.currentUser && window.currentUser.id) || ''),
141	      username:   String((window.currentUser && window.currentUser.username) || ''),
142	      message:    _sanitizeForErrorLog(entry.message).slice(0, 1000),
143	      source:     _sanitizeForErrorLog(entry.source).slice(0, 200),
144	      user_agent: (navigator.userAgent || '').slice(0, 300),
145	      url:        location.pathname,
146	      ts:         entry.ts
147	    };
148	    // ES5 호환: .finally() 미지원 환경 대비 — .then/.catch 양쪽에서 플래그 해제
149	    supaFetch('madi_error_logs', 'POST', [payload])
150	      .then(function() { window._errorLogSending = false; },
151	            function() { window._errorLogSending = false; }); // 의도적 무음: 에러 로그 전송 자체의 실패에 warn 찍으면 무한 루프 위험
152	  } catch(e) {
153	    window._errorLogSending = false;
154	  }
155	}
156	
157	function getErrorLog() {
158	  try { return JSON.parse(sessionStorage.getItem('madi_error_log') || '[]'); } catch(e) { return []; }
159	}
160	
161	function clearErrorLog() {
162	  showConfirm('에러 로그를 모두 삭제할까요?', function() {
163	    sessionStorage.removeItem('madi_error_log');
164	    renderDebugInfo();
165	    showToast('🗑️ 에러 로그 삭제됨');
166	  });
167	}
