169	// 디버그 정보 카드 렌더
170	function renderDebugInfo() {
171	  var el = document.getElementById('debugInfoBody');
172	  if (!el) return;
173	
174	  var logs = getErrorLog();
175	  var totalTokens = (apiUsage.inputTokens || 0) + (apiUsage.outputTokens || 0);
176	  var costUSD = estimateCost();
177	  var costKRW = Math.round(costUSD * 1380); // 환율 1380원/달러 (2026.05 기준)
178	
179	  var statCard = function(val, label, color) {
180	    return '<div style="flex:1;min-width:80px;background:#f8fafc;border-radius:10px;padding:10px;text-align:center;">'
181	      + '<div style="font-size:18px;font-weight:900;color:' + color + ';">' + val + '</div>'
182	      + '<div style="font-size:10px;font-weight:700;color:var(--text2);margin-top:2px;">' + label + '</div>'
183	      + '</div>';
184	  };
185	
186	  var modelHtml = '';
187	  Object.keys(apiUsage.byModel || {}).forEach(function(m) {
188	    var u = apiUsage.byModel[m];
189	    var label = m.includes('haiku') ? 'Haiku' : m.includes('sonnet') ? 'Sonnet' : m;
190	    modelHtml += '<div style="display:flex;align-items:center;justify-content:space-between;padding:6px 10px;background:#f8fafc;border-radius:7px;margin-bottom:4px;font-size:12px;">'
191	      + '<span style="font-weight:700;">' + label + '</span>'
192	      + '<span style="color:var(--text2);">' + u.calls + '회 · 입력 ' + u.inputTokens.toLocaleString() + ' / 출력 ' + u.outputTokens.toLocaleString() + '</span>'
193	      + '</div>';
194	  });
195	
196	  var html = '<div style="font-size:12px;font-weight:700;color:var(--navy);margin-bottom:8px;">📡 API 사용량</div>'
197	    + '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px;">'
198	    + statCard((apiUsage.calls || 0) + '회', '총 호출', 'var(--mint)')
199	    + statCard(totalTokens.toLocaleString(), '총 토큰', 'var(--purple)')
200	    + statCard('$' + costUSD.toFixed(2), '예상 비용', costUSD > 5 ? 'var(--amber)' : 'var(--green)')
201	    + statCard('₩' + costKRW.toLocaleString(), '원화 환산', costUSD > 5 ? 'var(--amber)' : 'var(--green)')
202	    + '</div>'
203	    + (modelHtml ? '<div style="margin-bottom:12px;">' + modelHtml + '</div>' : '')
204	    + '<div style="display:flex;gap:6px;margin-bottom:14px;">'
205	    + '<button class="btn-ghost" style="flex:1;font-size:12px;" onclick="resetApiUsage()">🔄 사용량 초기화</button>'
206	    + '</div>'
207	    + '<div style="font-size:12px;font-weight:700;color:var(--navy);margin-bottom:6px;">🐞 에러 로그 (최근 ' + logs.length + '건)</div>';
208	
209	  if (logs.length === 0) {
210	    html += '<div style="font-size:12px;color:var(--text2);text-align:center;padding:10px;">기록된 에러가 없습니다.</div>';
211	  } else {
212	    var recent = logs.slice(-5).reverse();
213	    html += recent.map(function(e) {
214	      var d = new Date(e.ts).toLocaleString('ko-KR');
215	      return '<div style="padding:7px 10px;background:#fef2f2;border-radius:7px;margin-bottom:4px;font-size:11px;line-height:1.5;">'
216	        + '<div style="color:#dc2626;font-weight:700;">' + escHtml(e.message || '오류') + '</div>'
217	        + '<div style="color:var(--text2);margin-top:2px;">' + d + (e.source ? ' · ' + escHtml(e.source) : '') + '</div>'
218	        + '</div>';
219	    }).join('');
220	    html += '<div style="display:flex;gap:6px;margin-top:8px;">'
221	      + '<button class="btn-ghost" style="flex:1;font-size:12px;" onclick="copyErrorLog()">📋 전체 로그 복사</button>'
222	      + '<button class="btn-del" style="flex:0.5;" onclick="clearErrorLog()">🗑️ 삭제</button>'
223	      + '</div>';
224	  }
225	
226	  el.innerHTML = html;
227	}
