229	function copyErrorLog() {
230	  var logs = getErrorLog();
231	  var usage = apiUsage;
232	  var text = '=== 마디 디버그 정보 ===\n'
233	    + '시간: ' + new Date().toLocaleString('ko-KR') + '\n'
234	    + 'UA: ' + navigator.userAgent + '\n\n'
235	    + '--- API 사용량 ---\n'
236	    + '총 호출: ' + (usage.calls || 0) + '회\n'
237	    + '입력 토큰: ' + (usage.inputTokens || 0) + '\n'
238	    + '출력 토큰: ' + (usage.outputTokens || 0) + '\n'
239	    + '예상 비용: $' + estimateCost().toFixed(2) + '\n\n'
240	    + '--- 에러 로그 ---\n'
241	    + logs.map(function(e) {
242	        return '[' + new Date(e.ts).toISOString() + '] ' + (e.message || '?') + (e.source ? ' @ ' + e.source : '');
243	      }).join('\n');
244	
245	  if (navigator.clipboard) {
246	    navigator.clipboard.writeText(text).then(function() {
247	      showToast('📋 디버그 정보 복사됨 — 붙여넣기로 전달하세요');
248	    });
249	  } else {
250	    showToast('클립보드 미지원 — 설정 > 디버그 화면을 캡처해 전달해주세요');
251	  }
252	}
