254	function setupGlobalErrorHandler() {
255	  window.addEventListener('error', function(e) {
256	    // CORS 등 무관한 에러는 무시
257	    if (!e.message || e.message === 'Script error.') return;
258	    var filename = (e.filename || '').split('/').pop() || '(unknown)';
259	    var src = filename + ':' + (e.lineno || '?') + (e.colno ? ':' + e.colno : '');
260	    console.error('[Global Error]', maskPII(e.message), src);
261	    pushErrorLog({
262	      ts: Date.now(),
263	      message: maskPII(e.message),
264	      source: src
265	    });
266	    // 디버깅 편의: 30초에 1회 (이전 5분에서 단축) — 진단 완료 후 다시 늘릴 것
267	    if (!window._lastErrorToast || Date.now() - window._lastErrorToast > 30000) {
268	      window._lastErrorToast = Date.now();
269	      try {
270	        var shortMsg = (e.message || '').slice(0, 70);
271	        showToast('⚠️ 오류: ' + shortMsg + ' @ ' + src, { duration: 7000 });
272	      } catch(e2) {}
273	    }
274	  });
275	  window.addEventListener('unhandledrejection', function(e) {
276	    var msg = e.reason && e.reason.message ? e.reason.message : String(e.reason);
277	    console.error('[Unhandled Promise]', maskPII(msg));
278	    pushErrorLog({ ts: Date.now(), message: 'Promise: ' + maskPII(msg), source: 'unhandledrejection' });
279	    if (!window._lastErrorToast || Date.now() - window._lastErrorToast > 30000) {
280	      window._lastErrorToast = Date.now();
281	      try {
282	        showToast('⚠️ 비동기 오류: ' + maskPII(msg).slice(0, 80), { duration: 7000 });
283	      } catch(e2) {}
284	    }
285	  });
286	}
