288	// ─────── 데이터 안전망: IndexedDB 자동 백업 ───────
289	var BACKUP_DB_NAME = 'madi_backup_db';
290	var BACKUP_STORE   = 'daily_backups';
291	var BACKUP_KEEP    = 7; // 7일치 보관
292	
293	function openBackupDB() {
294	  return new Promise(function(resolve, reject) {
295	    var req = indexedDB.open(BACKUP_DB_NAME, 1);
296	    req.onupgradeneeded = function(e) {
297	      var db = e.target.result;
298	      if (!db.objectStoreNames.contains(BACKUP_STORE)) {
299	        db.createObjectStore(BACKUP_STORE, { keyPath: 'id' });
300	      }
301	    };
302	    req.onsuccess = function(e) { resolve(e.target.result); };
303	    req.onerror   = function(e) { reject(e.target.error); };
304	  });
305	}
306	
307	function putBackup(record) {
308	  return openBackupDB().then(function(db) {
309	    return new Promise(function(resolve, reject) {
310	      var tx = db.transaction(BACKUP_STORE, 'readwrite');
311	      var store = tx.objectStore(BACKUP_STORE);
312	      var req = store.put(record);
313	      req.onsuccess = function() { resolve(); };
314	      req.onerror   = function(e) { reject(e.target.error); };
315	    });
316	  });
317	}
318	
319	function listBackups() {
320	  return openBackupDB().then(function(db) {
321	    return new Promise(function(resolve, reject) {
322	      var tx = db.transaction(BACKUP_STORE, 'readonly');
323	      var store = tx.objectStore(BACKUP_STORE);
324	      var req = store.getAll();
325	      req.onsuccess = function() {
326	        var arr = req.result || [];
327	        // 날짜 내림차순
328	        arr.sort(function(a, b) { return b.id.localeCompare(a.id); });
329	        resolve(arr);
330	      };
331	      req.onerror = function(e) { reject(e.target.error); };
332	    });
333	  });
334	}
335	
336	function getBackup(id) {
337	  return openBackupDB().then(function(db) {
338	    return new Promise(function(resolve, reject) {
339	      var tx = db.transaction(BACKUP_STORE, 'readonly');
340	      var req = tx.objectStore(BACKUP_STORE).get(id);
341	      req.onsuccess = function() { resolve(req.result); };
342	      req.onerror   = function(e) { reject(e.target.error); };
343	    });
344	  });
345	}
346	
347	function deleteBackup(id) {
348	  return openBackupDB().then(function(db) {
349	    return new Promise(function(resolve, reject) {
350	      var tx = db.transaction(BACKUP_STORE, 'readwrite');
351	      var req = tx.objectStore(BACKUP_STORE).delete(id);
352	      req.onsuccess = function() { resolve(); };
353	      req.onerror   = function(e) { reject(e.target.error); };
354	    });
355	  });
356	}
