358	// 간단한 체크섬 (FNV-1a 32bit) — 무결성 확인용
359	function quickHash(str) {
360	  var h = 2166136261;
361	  for (var i = 0; i < str.length; i++) {
362	    h ^= str.charCodeAt(i);
363	    h = (h * 16777619) >>> 0;
364	  }
365	  return h.toString(16);
366	}
367	
368	function buildBackupSnapshot() {
369	  var data = {
370	    children:    childDB    || [],
371	    sessions:    sessionDB  || [],
372	    schedule:    scheduleDB || [],
373	    assessments: assessmentDB || [],
374	    activities:  activityDB || [],
375	    iep:         iepDB      || []
376	  };
377	  var json = JSON.stringify(data);
378	  return {
379	    data: data,
380	    size: json.length,
381	    counts: {
382	      children:    data.children.length,
383	      sessions:    data.sessions.length,
384	      schedule:    data.schedule.length,
385	      assessments: data.assessments.length,
386	      activities:  data.activities.length,
387	      iep:         data.iep.length
388	    },
389	    checksum: quickHash(json)
390	  };
391	}
392	
393	function autoBackup() {
394	  // 데이터가 아예 없으면 백업 스킵
395	  if ((childDB || []).length === 0 && (sessionDB || []).length === 0) return Promise.resolve();
396	
397	  var dateKey = getTodayKST();
398	  var snapshot = buildBackupSnapshot();
399	  var record = Object.assign({ id: dateKey, createdAt: Date.now() }, snapshot);
400	
401	  return putBackup(record)
402	    .then(pruneOldBackups)
403	    .then(function() {
404	      localStorage.setItem('madi_last_backup', dateKey);
405	      if (window.console && console.debug) console.debug('[자동 백업] ' + dateKey + ' 저장됨 (' + Math.round(snapshot.size/1024) + 'KB)');
406	    })
407	    .catch(function(err) {
408	      console.error('[자동 백업 실패]', err);
409	    });
410	}
411	
412	function pruneOldBackups() {
413	  return listBackups().then(function(arr) {
414	    if (arr.length <= BACKUP_KEEP) return;
415	    var toDelete = arr.slice(BACKUP_KEEP);
416	    return Promise.all(toDelete.map(function(b) { return deleteBackup(b.id); }));
417	  });
418	}
419	
420	function maybeAutoBackup() {
421	  var last = localStorage.getItem('madi_last_backup');
422	  var todayKey = getTodayKST();
423	  if (last === todayKey) return; // 오늘 이미 백업
424	  // 약간 늦게 실행 (앱 로드 방해 안 하기)
425	  setTimeout(function() { autoBackup(); }, 5000);
426	}
