428	// ─────── 백업 복원 ───────
429	function restoreFromBackup(id) {
430	  showConfirm('⚠️ 백업 ' + id + ' 으로 복원하시겠습니까?\n\n현재 모든 데이터가 백업으로 덮어써집니다.\n복원 직전 자동으로 현재 상태도 백업됩니다.', function() {
431	    showConfirm('정말 진행하시겠습니까? 이 작업은 되돌릴 수 없습니다.', function() {
432	      _execRestoreFromBackup(id);
