558	function parseJSON(raw) {
559	  var cleaned = raw.replace(/```json|```/g, '').trim();
560	
561	  // 정상 파싱 시도
562	  var s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
563	  if (s < 0 || e < 0) {
564	    s = cleaned.indexOf('['); e = cleaned.lastIndexOf(']');
565	  }
566	  if (s >= 0 && e >= s) {
567	    try { return JSON.parse(cleaned.slice(s, e + 1)); } catch(ignored) {}
568	  }
569	
570	  // 잘린 JSON 복구 시도: 배열/객체 괄호 균형 맞추기
571	  try {
572	    var fragment = s >= 0 ? cleaned.slice(s) : cleaned;
573	    var depth = 0, inStr = false, escape = false, cutAt = fragment.length;
574	    for (var i = 0; i < fragment.length; i++) {
575	      var ch = fragment[i];
576	      if (escape) { escape = false; continue; }
577	      if (ch === '\\' && inStr) { escape = true; continue; }
578	      if (ch === '"') { inStr = !inStr; continue; }
579	      if (inStr) continue;
580	      if (ch === '{' || ch === '[') depth++;
581	      else if (ch === '}' || ch === ']') { depth--; if (depth === 0) { cutAt = i + 1; break; } }
582	    }
583	    if (depth > 0) {
584	      // 잘린 경우 — 열린 배열/객체 닫기
585	      var partial = fragment.slice(0, cutAt);
586	      // 마지막 완전한 콤마 이후 불완전 항목 제거
587	      var lastComma = partial.lastIndexOf(',');
588	      var closing = '';
589	      // 남은 depth 만큼 닫기
590	      var checkDepth = 0;
591	      for (var k = 0; k < partial.length; k++) {
592	        var c = partial[k];
593	        if (c === '"') { var q = partial.indexOf('"', k+1); if (q > k) k = q; continue; }
594	        if (c === '{' || c === '[') checkDepth++;
595	        else if (c === '}' || c === ']') checkDepth--;
596	      }
597	      if (lastComma > 0 && checkDepth > 0) {
598	        partial = partial.slice(0, lastComma);
599	        for (var d = 0; d < checkDepth; d++) closing += (fragment[0] === '[' ? ']' : '}');
600	        try { return JSON.parse(partial + closing); } catch(e2) {}
601	      }
602	    }
603	  } catch(ignored2) {}
604	
605	  throw new Error('JSON 응답 파싱 실패 — 응답이 너무 길거나 형식이 올바르지 않습니다.');
606	}
