345	function generateSIReport() {
346	  if (!canDo('useAI')) { showToast('⚠️ AI 기능 사용 권한이 없습니다'); return; }
347	  var apiKey = getApiKeyOrAlert();
348	  if (!apiKey) return;
349	
350	  var d = collectSIData();
351	  if (!d.child)     { showToast('아동을 선택해주세요.'); return; }
352	  if (!d.bg)        { showToast('배경 정보를 입력해주세요.'); return; }
353	  if (!d.attitude)  { showToast('검사 태도를 입력해주세요.'); return; }
354	  if (d.tests.length === 0) { showToast('실시한 검사를 1개 이상 선택해주세요.'); return; }
355	
356	  var btn    = document.getElementById('siReportBtn');
357	  var result = document.getElementById('siReportResult');
358	  if (btn.dataset.busy === '1') return;
359	  btn.dataset.busy = '1';
360	  btn.disabled = true;
361	  btn.textContent = '⏳ AI 보고서 작성 중...';
362	  result.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text2);">AI가 보고서를 작성하고 있습니다...</div>';
363	
364	  var NL = '\n';
365	  function fmtDevRow(r) {
366	    return '· ' + r.domain + ': ' + (r.result||'-') + ' / ' + (r.level||'-') + (r.note ? ' / 특이항목: ' + r.note : '');
367	  }
368	  var ddstText  = d.ddst && d.ddst.length > 0  ? d.ddst.map(fmtDevRow).join(NL)  : '입력 없음';
369	  var kdstText  = d.kdst && d.kdst.length > 0  ? d.kdst.map(fmtDevRow).join(NL)  : '입력 없음';
370	
371	  var sp2Text = d.sp2.length > 0
372	    ? d.sp2.map(function(r){
373	        return '· [' + r.section + '] ' + r.domain + ': ' + (r.level||'-') + (r.note ? ' (' + r.note + ')' : '');
374	      }).join(NL)
375	    : '입력 없음';
376	
377	  var patternText = d.sp2Patterns && d.sp2Patterns.length > 0
378	    ? d.sp2Patterns.map(function(r){
379	        return '· ' + r.label + ': ' + (r.level||'-') + (r.note ? ' — ' + r.note : '');
380	      }).join(NL)
381	    : '입력 없음';
382	
383	  var SYSTEM = '당신은 감각통합 분야 전문 작업치료사입니다. 평가 결과를 바탕으로 전문적이고 임상적으로 타당한 보고서 종합 소견과 치료 권고사항을 작성합니다. 한국어로 작성하며, 아동의 강점과 어려움을 균형 있게 기술합니다.';
384	
385	  var USER = '[아동 정보]' + NL
386	    + '이름: ' + d.child.name + ' / 성별: ' + (d.child.gender||'-') + ' / 생년월일: ' + (d.child.birth||'-') + ' / 생활연령: ' + (d.child.age||'-') + NL
387	    + '평가일: ' + d.date + ' / 정보제공자: ' + d.informant + NL + NL
388	    + '[I. 배경 정보]' + NL + d.bg + NL + NL
389	    + '[II. 검사 태도]' + NL + d.attitude + NL + NL
390	    + '[III. 실시한 검사]' + NL + d.tests.map(function(t){ return '· ' + t; }).join(NL) + NL + NL
391	    + '[IV-A. DDST 발달 검사 결과]' + NL + ddstText + NL + NL
392	    + '[IV-B. K-DST 발달 검사 결과]' + NL + kdstText + NL + NL
393	    + '[IV-C. SP2 감각 처리 영역별 결과]' + NL + sp2Text + NL + NL
394	    + '[IV-D. SP2 감각 처리 패턴]' + NL + patternText
395	    + (d.extra ? NL + NL + '[추가 의견]' + NL + d.extra : '') + NL + NL
396	    + '위 정보를 바탕으로 다음 두 섹션을 전문적으로 작성해주세요:' + NL
397	    + 'V. 종합 소견: 주요 발달 특성, 감각 처리 패턴, 기능적 영향을 3~5문단으로 서술' + NL
398	    + 'VI. 치료 권고사항: 감각통합치료 목표, 접근법, 가정 연계 지도 등을 구체적으로 서술';
399	
400	  callClaude(SYSTEM, USER, 2000, getAIModel())
401	    .then(function(raw) {
402	      var text = raw.trim();
403	      result.innerHTML = '<div style="border:1.5px solid var(--mint,#0ea5a0);border-radius:12px;padding:16px;margin-top:4px;">'
404	        + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">'
405	        + '<span style="font-weight:700;font-size:14px;color:var(--mint,#0ea5a0);">🤖 AI 생성 보고서</span>'
406	        + '<button onclick="copySIReport()" class="btn-ghost" style="font-size:11px;padding:5px 12px;">📋 복사</button>'
407	        + '</div>'
408	        + '<div id="siReportText" style="white-space:pre-wrap;font-size:13px;line-height:1.8;color:var(--text);">' + escHtml(text) + '</div>'
409	        + '</div>';
410	      showToast('✅ 감통 보고서 생성 완료!');
411	    })
412	    .catch(function(e) {
413	      result.innerHTML = '<div style="color:#ef4444;padding:10px;">❌ 오류: ' + escHtml(e.message||'알 수 없는 오류') + '</div>';
414	    })
415	    .finally(function() {
416	      btn.dataset.busy = '';
417	      btn.disabled = false;
418	      btn.textContent = '🤖 AI 감통 보고서 생성 (종합 소견 + 권고사항)';
419	    });
420	}
