450	    list.querySelectorAll('.si-custom-test'),
451	    function(el){ return el.dataset.name === name; }
452	  );
453	  var existsBuiltin = (typeof SI_TESTS !== 'undefined') && SI_TESTS.some(function(t){ return t.label === name; });
454	  if (existsCustom || existsBuiltin) { showToast('이미 추가된 검사입니다.'); return; }
455	
456	  // 안전한 DOM 생성 (innerHTML 인젝션 방지)
