459	  chip.dataset.name = name;
460	  chip.style.cssText = 'display:inline-flex;align-items:center;gap:4px;background:#fff;border:1px solid #ca8a04;color:#854d0e;border-radius:999px;padding:4px 4px 4px 10px;font-size:12px;font-weight:600;';
461	  var label = document.createElement('span');
462	  label.textContent = name;
463	  var btn = document.createElement('button');
464	  btn.type = 'button';
465	  btn.textContent = '×';
466	  btn.title = '삭제';
467	  btn.style.cssText = 'border:none;background:#fef3c7;color:#854d0e;width:20px;height:20px;border-radius:50%;cursor:pointer;font-size:14px;line-height:1;font-weight:700;';
468	  btn.onclick = function(){ removeCustomSITest(chip); };
469	  chip.appendChild(label);
470	  chip.appendChild(btn);
471	  list.appendChild(chip);
472	
473	  input.value = '';
474	  input.focus();
