481	// ─────── K-DST 발달수준 색상 시각화 ───────
482	// 또래수준(녹색) / 추적검사요망(주황) / 심화평가권고(빨강) — 위험도 한눈에 파악
483	function updateKdstLevelColor(selectEl) {
484	  if (!selectEl) return;
485	  var val = selectEl.value || '';
486	  // 색상 매핑 (좌측 border + 우측 점)
487	  var colorMap = {
488	    '또래수준':     '#16a34a', // 녹색 — 정상
489	    '추적검사요망': '#ca8a04', // 주황 — 주의·관찰 필요
490	    '심화평가권고': '#dc2626'  // 빨강 — 즉시 평가 필요
