98	// ─────── 마크다운 → HTML 변환 (보고서 표 렌더링용) ───────
99	function markdownToHtml(text) {
100	  var lines = text.split('\n');
101	  var html = '';
102	  var inTable = false;
103	  var tableRows = [];
104	
105	  function flushTable() {
106	    if (!tableRows.length) return;
107	    html += '<table style="width:100%;border-collapse:collapse;margin:10px 0;font-size:13px;">';
108	    tableRows.forEach(function(row, ri) {
109	      html += '<tr>';
110	      row.forEach(function(cell) {
111	        var tag = ri === 0 ? 'th' : 'td';
112	        var style = 'border:1px solid #cbd5e1;padding:7px 10px;';
113	        if (ri === 0) style += 'background:#f0fdf4;font-weight:700;color:#0f2942;text-align:center;';
114	        html += '<' + tag + ' style="' + style + '">' + escHtml(cell.trim()) + '</' + tag + '>';
115	      });
116	      html += '</tr>';
117	    });
118	    html += '</table>';
119	    inTable = false;
120	    tableRows = [];
121	  }
122	
123	  lines.forEach(function(line) {
124	    var trimmed = line.trim();
125	    // ** 볼드 인라인 변환 (PDF/Word 출력용)
126	    function inlineBold(str) {
127	      return escHtml(str).replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>').replace(/\*([^*]+)\*/g, '<i>$1</i>');
128	    }
129	    if (trimmed.startsWith('|')) {
130	      if (!inTable) inTable = true;
131	      if (/^\|[-:\s|]+\|$/.test(trimmed)) return; // 구분선 행 건너뜀
132	      var cells = trimmed.split('|').filter(function(_, i, a) { return i > 0 && i < a.length - 1; });
133	      tableRows.push(cells);
134	    } else {
135	      if (inTable) flushTable();
136	      if (trimmed === '') {
137	        html += '<div style="height:6px;"></div>';
138	      } else if (/^(I|II|III|IV|V|VI|VII)\./.test(trimmed)) {
139	        html += '<h2 style="font-size:15px;font-weight:700;color:#0f2942;margin:20px 0 8px;border-bottom:2px solid #0ea5a0;padding-bottom:5px;">' + inlineBold(trimmed) + '</h2>';
140	      } else if (/^\d+\./.test(trimmed) && trimmed.length < 60) {
141	        html += '<p style="font-weight:700;font-size:14px;margin:12px 0 4px;color:#1e293b;">' + inlineBold(trimmed) + '</p>';
142	      } else if (/^[가-힣]\./.test(trimmed)) {
143	        html += '<p style="font-weight:700;font-size:13px;margin:8px 0 4px;color:#0ea5a0;">' + inlineBold(trimmed) + '</p>';
144	      } else if (trimmed.startsWith('- ') || trimmed.startsWith('• ')) {
145	        html += '<p style="margin:3px 0;padding-left:14px;font-size:13px;line-height:1.8;">• ' + inlineBold(trimmed.slice(2)) + '</p>';
146	      } else {
147	        html += '<p style="margin:3px 0;font-size:13px;line-height:1.8;">' + inlineBold(line) + '</p>';
148	      }
149	    }
150	  });
151	  if (inTable) flushTable();
152	  return html;
153	}
